using System;using System.Drawing;using System.Text;namespace Mapping{    /// <summary>    ///     /// </summary>    public class Bin    {        private static BinColorManager ColorManager = new BinColorManager();        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="work"></param>        public Bin(BinCode binCode, bool work)            : this(binCode, work, string.Empty, ColorManager.Next())        {        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="work"></param>        /// <param name="description"></param>        public Bin(BinCode binCode, bool work, string description)            : this(binCode, work, description, ColorManager.Next())        {        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="work"></param>        /// <param name="description"></param>        /// <param name="color"></param>        public Bin(BinCode binCode, bool work, string description, Color color)        {            if (binCode == null)            {                throw new ArgumentNullException(nameof(binCode));            }            this.Code = binCode;            this.Work = work;            this.Description = description;            this.Color = color;        }        /// <summary>        ///         /// </summary>        /// <param name="other"></param>        public Bin(Bin other)        {            if (other == null)            {                throw new ArgumentNullException(nameof(other));            }            this.Code = other.Code;            this.Work = other.Work;            this.Count = other.Count;            this.Description = other.Description;            this.Color = other.Color;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <returns></returns>        public static Bin CreateNullBin(char binCode)        {            return new Bin(new BinCode(binCode), false);        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <returns></returns>        public static Bin CreateEmptyBin(char binCode)        {            return new Bin(new BinCode(binCode), true);        }        /// <summary>        ///         /// </summary>        /// <param name="formatType"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static Bin CreateNullBin(BinFormatType formatType, string binCode)        {            return new Bin(new BinCode(formatType, binCode), false);        }        /// <summary>        /// A bin category, other that the value assigned to        /// NullBin, that may be assigned to a device.        /// It should be represented according to <see cref="BinFormatType"/>.        /// </summary>        public BinCode Code { get; private set; }        /// <summary>        ///         /// </summary>        public string FormattedCode        {            get => this.Code.FormattedCode;        }        /// <summary>        /// The number of devices on the substrate with the specified BinCode.        /// </summary>        public int Count { get; internal set; }        /// <summary>        /// A description of the specified BinCode (e.g., "100MHz").        /// </summary>        public string Description { get; set; }        /// <summary>        /// Bin color.        /// </summary>        public Color Color { get; set; }        private bool work;        /// <summary>        /// Indicates that devices whith this BinCode should be processed or not.        /// Work = True indicates that devices whith this BinCode should be processed.        /// Work = False indicates that devices whith this BinCode should not be processed.        /// </summary>        public bool Work        {            get => this.work;            set            {                if (value != this.work)                {                    this.work = value;                }            }        }        /// <summary>        ///         /// </summary>        /// <param name="obj"></param>        /// <returns></returns>        public override bool Equals(object obj)        {            return this.Equals(obj as Bin);        }        /// <summary>        ///         /// </summary>        /// <param name="obj"></param>        /// <returns></returns>        public bool Equals(Bin obj)        {            if ((obj as object) == null)            {                return false;            }            bool equal = (this.Code == obj.Code);            return equal;        }        /// <summary>        ///         /// </summary>        /// <returns></returns>        public override int GetHashCode()        {            return Code.GetHashCode();        }        /// <summary>        ///         /// </summary>        /// <returns></returns>        public override string ToString()        {            StringBuilder sb = new StringBuilder(this.FormattedCode);            if (!string.IsNullOrEmpty(this.Description))            {                sb.Append($" - {this.Description}");            }            return sb.ToString();        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator ==(Bin left, Bin right)        {            if ((left as object) == null)            {                return ((right as object) == null);            }            return left.Equals(right);        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator !=(Bin left, Bin right)        {            return !(left == right);        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator ==(Bin left, ushort binCode)        {            return left.Code == binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator !=(Bin left, ushort binCode)        {            return left.Code != binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator ==(ushort binCode, Bin right)        {            return binCode == right.Code;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator !=(ushort binCode, Bin right)        {            return binCode != right.Code;        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator ==(Bin left, char binCode)        {            return left.Code == binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="left"></param>        /// <param name="binCode"></param>        /// <returns></returns>        public static bool operator !=(Bin left, char binCode)        {            return left.Code != binCode;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator ==(char binCode, Bin right)        {            return binCode == right.Code;        }        /// <summary>        ///         /// </summary>        /// <param name="binCode"></param>        /// <param name="right"></param>        /// <returns></returns>        public static bool operator !=(char binCode, Bin right)        {            return binCode != right.Code;        }    }}